from bs4 import BeautifulSoup
def task_func(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')
        dicts = []
        for script in scripts:
            text = script.string
            if text:
                try:
                    d = ast.literal_eval(text.strip())
                    if isinstance(d, dict):
                        dicts.append(d)
                except (ValueError, SyntaxError):
                    continue
        return dicts
    except Exception:
        return []

import requests
import logging
def task_func(repo_url: str) -> dict:
    if not isinstance(repo_url, str) or not repo_url:
        raise ValueError("Invalid repository URL provided.")
    try:
        response = requests.get(repo_url, verify=False)
        if response.status_code == 403 and 'X-RateLimit-Remaining' in response.headers:
            remaining = int(response.headers.get('X-RateLimit-Remaining', 0))
            if remaining == 0:
                raise requests.exceptions.HTTPError("GitHub API rate limit exceeded.")
        response.raise_for_status()
        repo_info = response.json()
        open_issues = repo_info.get('open_issues_count', 0)
        if open_issues > 100:
            logging.warning(f"Repository has a large number of open issues: {open_issues}")
        return repo_info
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}")

