import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s/$.?#].[^\s]*'
    urls = re.findall(url_pattern, myString)
    result = {}
    for url in urls:
        try:
            parsed = urllib.parse.urlparse(url)
            domain = parsed.netloc
            if not domain:
                continue
            response = requests.get(f"http://ip-api.com/json/{domain}?fields=status,country,region,city,lat,lon,isp,org,as,query&access_key={API_KEY}")
            if response.status_code == 200:
                data = response.json()
                result[domain] = data
            else:
                result[domain] = None
        except Exception:
            result[domain] = None
    return result

import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError:
        raise ValueError("Invalid IP range provided.")

    active_ips = []
    for ip in network.hosts():
        try:
            response = requests.get(f"http://{ip}", timeout=timeout)
            if response.status_code == 200:
                active_ips.append(str(ip))
        except requests.RequestException:
            continue
    return active_ips

