import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        response = requests.get(url, headers=HEADERS, params=parameters)
        response.raise_for_status()
        data = response.json()
        if not data:
            raise Exception("Empty data received from API.")
        df = pd.DataFrame(data)
        if df.empty:
            raise Exception("DataFrame is empty after conversion.")
        numeric_df = df.select_dtypes(include=['number'])
        if numeric_df.empty:
            raise Exception("No numeric columns available for correlation.")
        corr_matrix = numeric_df.corr()
        fig, ax = plt.subplots()
        sns.heatmap(corr_matrix, annot=True, fmt=".2f", ax=ax)
        ax.set_title("Correlation Heatmap")
        plt.tight_layout()
        return df, ax
    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to access URL: {e}")
    except (json.JSONDecodeError, ValueError) as e:
        raise Exception(f"Invalid data format: {e}")
    except Exception as e:
        raise Exception(f"Error: {e}")

from flask import Flask
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalAPI(Resource):
        def get(self):
            try:
                response = requests.get(api_url)
                response.raise_for_status()
                return response.json()
            except requests.RequestException as e:
                return {"error": str(e)}, 500

    api.add_resource(ExternalAPI, '/api/data')
    return app

import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    response = requests.get(URL + username)
    response.raise_for_status()
    data = response.json()
    normalized = {}
    for key, value in data.items():
        if isinstance(value, str):
            normalized[key] = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode()
        else:
            normalized[key] = value
    return normalized
